3	import RelatorioNav from './RelatorioNav';
4	import FiltroPeriodo from './FiltroPeriodo';
5	import { fmt, buildRange, printIframe, reportBaseStyle, printFooterScript, defaultFiltroState } from '../../utils/relatorioPrint';
6	
7	const dataHora = (iso) => iso ? new Date(iso).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }) : '—';
8	const agora = () => new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
