31	    <td class="right">${fmt(v.taxa_cartao)}</td>
32	    <td>${traduzFormas(v.formas_pagamento)}</td>
33	    <td class="right bold">${fmt(v.total_geral)}</td>
34	  </tr>`).join('');
35	
36	  const vTotal = (vendas ?? []).reduce((s, v) => s + v.total, 0);
37	  const vGorjeta = (vendas ?? []).reduce((s, v) => s + v.gorjeta, 0);
