45	    <td></td>
46	    <td class="right bold">${fmt(vTotalGeral)}</td>
47	  </tr>` : '';
48	
49	  return `<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Relatório Garçom</title>
50	<style>${reportBaseStyle}</style></head><body>
51	<h1>${restauranteNome ?? 'RESTAURANTE'}</h1>
52	<div class="sub">Relatório por Garçom${garcomNome ? ` — ${garcomNome}` : ''} — ${label}</div>
53	<table>
54	  <tr><th>Garçom</th><th class="right">Total Vendido</th><th class="right">Comissão</th><th class="right">Gorjeta</th><th class="right">Total a Receber</th><th class="right">Comandas Abertas</th><th class="right">Pendentes</th></tr>
55	  ${rows || '<tr><td colspan="7">Nenhum garçom com movimento no período.</td></tr>'}
56	</table>
57	<div class="sub" style="margin-top:16px">Detalhamento das vendas</div>
58	<table>
59	  <tr><th>Data/Hora</th><th>Garçom</th><th>Comanda/Mesa</th><th>Cliente</th><th class="right">Total</th><th class="right">Gorjeta</th><th class="right">Taxa Cartão</th><th>Pagamento</th><th class="right">Total Geral</th></tr>
60	  ${vendaRows || '<tr><td colspan="9">Nenhuma venda no período.</td></tr>'}
61	  ${vendaTotalRow}
