82	const RelatorioGarcom = () => {
83	  const [restauranteNome, setRestauranteNome] = useState('');
84	  const [filtro, setFiltro] = useState(defaultFiltroState());
85	  const [garcons, setGarcons] = useState(null);
86	  const [vendas, setVendas] = useState([]);
87	  const [label, setLabel] = useState('');
88	  const [garcomId, setGarcomId] = useState('');
89	  const [loading, setLoading] = useState(false);
90	  const [erro, setErro] = useState(null);
91	  const [rangeAtual, setRangeAtual] = useState(null);
92	  const [marcandoPago, setMarcandoPago] = useState(null);
93	  const [repasseModal, setRepasseModal] = useState(null);
94	  const [valorDinheiro, setValorDinheiro] = useState('');
95	  const [valorPix, setValorPix] = useState('');
96	  const [busca, setBusca] = useState('');
97	  const [sortCampo, setSortCampo] = useState('total_vendido');
98	  const [expandido, setExpandido] = useState(null);
99	
