104	  const buscar = async () => {
105	    const range = buildRange(filtro.modo, filtro.dia, filtro.mes, filtro.ano, filtro.periodoIni, filtro.periodoFim);
106	    if (!range) return;
107	    setLoading(true); setErro(null);
108	    try {
109	      const d = await getRelatorioGarcom(range.de, range.ate);
