111	      setVendas(d.vendas ?? []);
112	      setLabel(range.label);
113	      setRangeAtual(range);
114	    } catch (e) { setErro(e.message); }
115	    finally { setLoading(false); }
116	  };
117	
118	  const abrirRepasse = (g) => {
119	    setErro(null);
120	    setRepasseModal(g);
121	    setValorDinheiro((g.total_gorjeta + g.total_comissao).toFixed(2));
122	    setValorPix('0.00');
123	  };
124	
125	  const confirmarRepasse = async () => {
126	    if (!rangeAtual || !repasseModal) return;
127	    const total = repasseModal.total_gorjeta + repasseModal.total_comissao;
128	    const vd = Number(valorDinheiro || 0);
129	    const vp = Number(valorPix || 0);
