142	        valor_pix: vp,
143	      });
144	      setRepasseModal(null);
145	      await buscar();
146	    } catch (e) { setErro(e.message); }
147	    finally { setMarcandoPago(null); }
148	  };
149	
150	  const estornarRepasse = async (g) => {
