183	
184	  return (
185	    <div className="min-h-screen bg-[#FAFAFA] dark:bg-[#18181B]">
186	      <RelatorioNav titulo="Garçom" />
187	      <main className="p-6 max-w-5xl mx-auto space-y-4">
188	        <FiltroPeriodo
189	          filtro={filtro} setFiltro={setFiltro} onBuscar={buscar} loading={loading}
