191	        />
192	
193	        {garcons && garcons.length > 0 && (
194	          <div className="bg-white dark:bg-[#27272A] rounded-2xl border border-[#E4E4E7] dark:border-[#3F3F46] p-4 flex flex-wrap gap-3 items-end">
