227	
228	        {erro && <p className="text-sm text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-950/40 px-3 py-2 rounded-xl">{erro}</p>}
229	
230	        {garcons && (
231	          <>
232	            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
