236	              </div>
237	              <div className="bg-white dark:bg-[#27272A] border border-[#E4E4E7] dark:border-[#3F3F46] rounded-2xl p-4 text-center">
238	                <p className="text-[10px] font-black text-[#71717A] dark:text-[#A1A1AA] uppercase tracking-widest mb-1">Comissão Total</p>
239	                <p className="text-2xl font-black text-[#18181B] dark:text-[#F4F4F5]">{fmt(totalComissao)}</p>
