async getRelatorioGarcom(restaurantId: number, de: string, ate: string) {
  const { data: garcons } = await this.supabase.client
    .from('garcons')
    .select('id, nome')
    .eq('restaurant_id', restaurantId);

  const { data: pedidos } = await this.supabase.client
    .from('orders')
    .select('id, total, status, canal, garcom_id, gorjeta_valor, created_at, numero_comanda, mesa_id, cliente_mesa_nome, customer_id, mesas(numero, nome), customers(name)')
    .eq('restaurant_id', restaurantId)
    .eq('canal', 'presencial')
    .not('garcom_id', 'is', null)
    .gte('created_at', de)
    .lte('created_at', ate);

  const orderIds = (pedidos ?? []).map((p: any) => p.id);
  const { data: comissoes } = orderIds.length
    ? await this.supabase.client
        .from('garcom_comissoes_lancamentos')
        .select('garcom_id, order_id, valor_calculado')
        .in('order_id', orderIds)
    : { data: [] as any[] };

  const pagamentosPorComanda = await this.buscarPagamentosPorComanda(pedidos ?? []);

  const { data: comandasAtuais } = await this.supabase.client
    .from('orders')
    .select('id, garcom_id, status')
    .eq('restaurant_id', restaurantId)
    .eq('canal', 'presencial')
    .not('garcom_id', 'is', null)
    .in('status', this.COMANDA_STATUS_ABERTOS);

  const porGarcom = new Map<number, any>();
  for (const g of (garcons ?? []) as any[]) {
    porGarcom.set(g.id, {
      garcom_id: g.id,
      nome: g.nome,
      total_vendido: 0,
      total_comissao: 0,
      total_gorjeta: 0,
      comandas_abertas: 0,
      comandas_pendentes: 0,
    });
  }

  for (const p of (pedidos ?? []) as any[]) {
    if (p.status !== 'paga') continue;
    const row = porGarcom.get(p.garcom_id);
    if (!row) continue;
    row.total_vendido += p.total ?? 0;
    row.total_gorjeta += p.gorjeta_valor ?? 0;
  }

  for (const c of (comissoes ?? []) as any[]) {
    const row = porGarcom.get(c.garcom_id);
    if (!row) continue;
    row.total_comissao += c.valor_calculado ?? 0;
  }

  // Produto favorito de cada garçom: agrega quantidade/receita por produto entre as
  // comandas pagas do período, reaproveitando o mesmo padrão de prodMap do getRelatorio.
  const pedidosPagos = (pedidos ?? []).filter((p: any) => p.status === 'paga');
  const garcomPorOrderId = new Map<number, number>(pedidosPagos.map((p: any) => [p.id, p.garcom_id]));
  const orderIdsPagos = pedidosPagos.map((p: any) => p.id);
  const { data: itemsGarcom } = orderIdsPagos.length
    ? await this.supabase.client
        .from('order_items')
        .select('order_id, product_id, quantity, unit_price')
        .in('order_id', orderIdsPagos)
    : { data: [] as any[] };

  const productIdsGarcom = [...new Set<number>((itemsGarcom ?? []).map((i: any) => i.product_id))];
  const { data: produtosGarcom } = productIdsGarcom.length
    ? await this.supabase.client.from('products').select('id, name').in('id', productIdsGarcom)
    : { data: [] as any[] };
  const prodNomeMap = Object.fromEntries((produtosGarcom ?? []).map((p: any) => [p.id, p.name]));

  const produtosPorGarcom = new Map<number, Map<number, { name: string; quantidade: number; receita: number }>>();
  for (const i of (itemsGarcom ?? []) as any[]) {
    const garcomId = garcomPorOrderId.get(i.order_id);
    if (!garcomId || !porGarcom.has(garcomId)) continue;
    if (!produtosPorGarcom.has(garcomId)) produtosPorGarcom.set(garcomId, new Map());
    const mapaProdutos = produtosPorGarcom.get(garcomId)!;
    if (!mapaProdutos.has(i.product_id)) {
      mapaProdutos.set(i.product_id, { name: prodNomeMap[i.product_id] ?? `#${i.product_id}`, quantidade: 0, receita: 0 });
    }
    const row = mapaProdutos.get(i.product_id)!;
    row.quantidade += i.quantity ?? 0;
    row.receita += (i.quantity ?? 0) * (i.unit_price ?? 0);
  }
  for (const [garcomId, mapaProdutos] of produtosPorGarcom) {
    porGarcom.get(garcomId).produtos = [...mapaProdutos.values()]
      .sort((a, b) => b.quantidade - a.quantidade)
      .slice(0, 5);
  }
  for (const row of porGarcom.values()) {
    if (!row.produtos) row.produtos = [];
  }

  for (const c of (comandasAtuais ?? []) as any[]) {
    const row = porGarcom.get(c.garcom_id);
    if (!row) continue;
    if (c.status === 'aberta') row.comandas_abertas++;
    if (c.status === 'fechada_garcom') row.comandas_pendentes++;
  }

  const { data: repasses } = await this.supabase.client
    .from('garcom_repasses')
    .select('id, garcom_id, valor_gorjeta, valor_comissao, pago_em')
    .eq('restaurant_id', restaurantId)
    .eq('periodo_de', de)
    .eq('periodo_ate', ate);
  const repassePorGarcom = new Map<number, any>((repasses ?? []).map((r: any) => [r.garcom_id, r]));
  for (const row of porGarcom.values()) {
    row.repasse = repassePorGarcom.get(row.garcom_id) ?? null;
  }

  const nomeGarcom = new Map<number, string>((garcons ?? []).map((g: any) => [g.id, g.nome]));
  const vendas = (pedidos ?? [])
    .filter((p: any) => p.status === 'paga')
    .map((p: any) => {
      const pagamentos = pagamentosPorComanda.get(p.id) ?? [];
      const taxa_cartao = pagamentos.reduce((s, pg) => s + (pg.taxa_cartao_valor ?? 0), 0);
      const formas_pagamento = pagamentos.length
        ? [...new Set(pagamentos.map((pg) => pg.forma_pagamento))].join(' + ')
        : null;
      const gorjeta = p.gorjeta_valor ?? 0;
      return {
        order_id: p.id,
        numero_comanda: p.numero_comanda,
        garcom_id: p.garcom_id,
        garcom_nome: nomeGarcom.get(p.garcom_id) ?? '—',
        mesa_numero: p.mesas?.numero ?? null,
        mesa_nome: p.mesas?.nome ?? null,
        cliente_nome: p.customers?.name ?? p.cliente_mesa_nome ?? null,
        data: p.created_at,
        total: p.total ?? 0,
        gorjeta,
        taxa_cartao,
        formas_pagamento,
        total_geral: (p.total ?? 0) + gorjeta + taxa_cartao,
      };
    })
    .sort((a, b) => new Date(a.data).getTime() - new Date(b.data).getTime());

  return { garcons: Array.from(porGarcom.values()), vendas };
}

// Dono clica "Marcar como pago" na linha do garçom, pro período em foco no relatório —
// registra que a gorjeta + comissão calculadas ali já foram repassadas. UNIQUE
// (garcom_id, periodo_de, periodo_ate) impede marcar duas vezes o mesmo período.
async registrarRepasseGarcom(
  restaurantId: number,
  garcomId: number,
  body: {
    de: string; ate: string; valor_gorjeta: number; valor_comissao: number;
    valor_dinheiro?: number; valor_pix?: number;
  },
) {
  const { data: garcom } = await this.supabase.client
    .from('garcons')
    .select('id, nome')
    .eq('id', garcomId)
    .eq('restaurant_id', restaurantId)
    .maybeSingle();
  if (!garcom) throw new NotFoundException('Garçom não encontrado neste restaurante');

  const total = Number((body.valor_gorjeta ?? 0) + (body.valor_comissao ?? 0));
  const valorDinheiro = Number(body.valor_dinheiro ?? 0);
  const valorPix = Number(body.valor_pix ?? 0);
  if (Math.abs(valorDinheiro + valorPix - total) > 0.01) {
    throw new BadRequestException('Soma dos valores por forma de pagamento não bate com o total a repassar');
  }

  // Repasse em dinheiro sai do caixa igual qualquer outra sangria — precisa de caixa
  // aberto pra vincular a baixa. Repasse em PIX não mexe no caixa físico. Guarda
  // caixa_id + criado_em da saída gerada pra dar pra estornar essa baixa específica
  // depois, se o dono marcar o repasse como "não pago" de novo por engano.
  let saidaCaixaId: number | null = null;
  let saidaCriadoEm: string | null = null;
  if (valorDinheiro > 0) {
    const saida = await this.adicionarSaida(restaurantId, {
      descricao: `Repasse gorjeta/comissão - ${garcom.nome}`,
      valor: valorDinheiro,
      meio: 'dinheiro',
    });
    saidaCaixaId = saida.caixa_id;
    saidaCriadoEm = saida.criado_em;
  }

  const { data, error } = await this.supabase.client
    .from('garcom_repasses')
    .insert({
      restaurant_id: restaurantId,
      garcom_id: garcomId,
      periodo_de: body.de,
      periodo_ate: body.ate,
      valor_gorjeta: body.valor_gorjeta ?? 0,
      valor_comissao: body.valor_comissao ?? 0,
      valor_dinheiro: valorDinheiro,
      valor_pix: valorPix,
      caixa_id: saidaCaixaId,
      saida_criado_em: saidaCriadoEm,
    })
    .select('id, valor_gorjeta, valor_comissao, valor_dinheiro, valor_pix, pago_em')
    .single();

  if (error) {
    // Já tinha dado baixa no caixa — se o registro do repasse falhar (ex: período já
    // marcado por outra aba), desfaz a saída pra não deixar o caixa com sangria órfã.
    if (saidaCaixaId && saidaCriadoEm) {
      await this.removerSaidaPorCriadoEm(restaurantId, saidaCaixaId, saidaCriadoEm).catch(() => {});
    }
    if (error.code === '23505') throw new ConflictException('Esse período já foi marcado como pago pra esse garçom.');
    throw error;
  }
  return data;
}

// Reverte um repasse marcado como pago por engano — apaga o registro (o UNIQUE de
// período libera pra pagar de novo, corrigido) e, se tinha baixa em dinheiro no caixa,
// estorna essa saída também. Só funciona se o caixa daquela baixa ainda estiver aberto.
async estornarRepasseGarcom(restaurantId: number, repasseId: number) {
  const { data: repasse, error: erroSelect } = await this.supabase.client
    .from('garcom_repasses')
    .select('id, valor_dinheiro, caixa_id, saida_criado_em')
    .eq('id', repasseId)
    .eq('restaurant_id', restaurantId)
    .maybeSingle();
  if (erroSelect) throw erroSelect;
  if (!repasse) throw new NotFoundException('Repasse não encontrado');

  if (repasse.valor_dinheiro > 0 && repasse.caixa_id && repasse.saida_criado_em) {
    await this.removerSaidaPorCriadoEm(restaurantId, repasse.caixa_id, repasse.saida_criado_em);
  }

  const { error } = await this.supabase.client.from('garcom_repasses').delete().eq('id', repasseId);
  if (error) throw error;
  return { ok: true };
}

// Relatório Produtos: lista/sem-estoque/ativos-bloqueados são estado atual (não filtrados
// por período); vendas (quantidade/receita por produto) são recortadas pelo período de/ate.
async getRelatorioProdutos(restaurantId: number, de: string, ate: string) {
  const { data: produtosData } = await this.supabase.client
    .from('products')
    .select('id, name, price, preco_custo, is_active, quantidade_estoque, quantidade_minima, category_id, categories(name)')
    .eq('restaurant_id', restaurantId)
    .order('name');

  const produtos = (produtosData ?? []).map((p: any) => ({ ...p, category_name: p.categories?.name ?? 'Outros' }));

  const { data: orders } = await this.supabase.client
    .from('orders')
    .select('id')
    .eq('restaurant_id', restaurantId)
    .gte('created_at', de)
    .lte('created_at', ate)
    .in('status', this.STATUS_VENDA_FINALIZADA);

